namespace CodeWalker {
 public partial class WorldForm {
  ClxnFlowCard clxnWardrobe;ComboBox clxnClothingComponent;NumericUpDown clxnClothingDrawable,clxnClothingTexture,clxnClothingAlt;Label clxnClothingFiles;Button clxnClothingApply;bool clxnClothingUpdating;string clxnClothingStatusKey;YddFile clxnWardrobeYdd;YtdFile clxnWardrobeYtd;
  string clxnWardrobeActor,clxnClothingYdd="",clxnClothingYtd="";
  void ClxnBuildWardrobe(){
   clxnVehicleSettings=new FlowLayoutPanel{Location=new Point(16,12),Size=new Size(888,36),WrapContents=false,Visible=false};clxnOptions.Controls.Add(clxnVehicleSettings);clxnVehicleSettings.Controls.Add(ClxnStyle.Label("МАШИНА",9,ClxnStyle.Muted));clxnVehicleCombo=new ComboBox{Width=295,DropDownStyle=ComboBoxStyle.DropDown,BackColor=ClxnStyle.Background,ForeColor=ClxnStyle.Text,FlatStyle=FlatStyle.Flat};clxnVehicleCombo.Items.AddRange(new object[]{"Ubermacht Oracle XS · Majestic","Lampadati Felon · Majestic"});clxnVehicleCombo.SelectedIndex=0;clxnVehicleSettings.Controls.Add(clxnVehicleCombo);clxnVehicleSettings.Controls.Add(ClxnStyle.Label("Поворот — в Объектах",9,ClxnStyle.Muted));
   clxnActorSettings.Controls.Add(ClxnStyle.Button("Одежда…",(s,e)=>ClxnOpenWardrobe(),110));
   clxnWardrobe=ClxnSidePanel(540);clxnWardrobe.Controls.Add(ClxnStyle.Label("ОДЕЖДА ПЕРСОНАЖА",10));clxnWardrobe.Controls.Add(new Label{Width=300,Height=53,Text="Одежда из вашей GTA V или отдельных YDD/YTD. Доступные номера определяются автоматически.",ForeColor=ClxnStyle.Muted});
   clxnClothingComponent=new ComboBox{Width=300,DropDownStyle=ComboBoxStyle.DropDownList};clxnClothingComponent.Items.AddRange(new object[]{"0 · Голова","1 · Маска","2 · Волосы","3 · Руки / торс","4 · Брюки","5 · Сумка","6 · Обувь","7 · Аксессуары","8 · Нижний слой","9 · Бронежилет","10 · Декали","11 · Верхняя одежда"});clxnClothingComponent.SelectedIndex=11;clxnClothingComponent.SelectedIndexChanged+=(s,e)=>ClxnShowClothing();clxnWardrobe.Controls.Add(clxnClothingComponent);
   clxnClothingDrawable=ClxnClothingNumber("Вариант / индекс модели YDD",10000);clxnClothingTexture=ClxnClothingNumber("Текстура / индекс в YTD",10000);clxnClothingAlt=ClxnClothingNumber("Альтернатива",255);
   clxnClothingFiles=new Label{Width=300,Height=80,AutoEllipsis=true,ForeColor=ClxnStyle.Muted};clxnWardrobe.Controls.Add(clxnClothingFiles);
   var imports=ClxnRow();imports.Controls.Add(ClxnStyle.Button("Подключить YDD…",(s,e)=>ClxnChooseClothing(false),145));imports.Controls.Add(ClxnStyle.Button("Текстуры YTD…",(s,e)=>ClxnChooseClothing(true),145));clxnWardrobe.Controls.Add(imports);
   clxnClothingApply=ClxnStyle.Button("Применить одежду",(s,e)=>ClxnSaveClothing(false),300,true);clxnWardrobe.Controls.Add(clxnClothingApply);clxnWardrobe.Controls.SetChildIndex(clxnClothingApply,2);clxnClothingDrawable.ValueChanged+=(s,e)=>{if(!clxnClothingUpdating)ClxnUpdateClothingLimits();};clxnWardrobe.Controls.Add(ClxnStyle.Button("Вернуть базовую деталь",(s,e)=>ClxnSaveClothing(true),300));clxnWardrobe.Controls.Add(ClxnStyle.Button("Использовать одежду GTA V",(s,e)=>{clxnClothingYdd=clxnClothingYtd="";clxnWardrobeYdd=null;clxnWardrobeYtd=null;ClxnUpdateClothingLimits();},300));
  }
  NumericUpDown ClxnClothingNumber(string label,int maximum){clxnWardrobe.Controls.Add(ClxnStyle.Label(label,9,ClxnStyle.Muted));var n=new NumericUpDown{Width=300,Maximum=maximum,BackColor=ClxnStyle.Background,ForeColor=ClxnStyle.Text};clxnWardrobe.Controls.Add(n);return n;}
  void ClxnOpenWardrobe(){var p=ClxnSelectedPin();if(p==null||!p.IsPed){clxnMessage="Выберите персонажа в Объектах, затем откройте его одежду.";return;}clxnEnvironment.Visible=false;clxnWardrobeActor=p.Id;clxnLibrary.Visible=clxnLogPanel.Visible=clxnFlightPanel.Visible=false;ClxnShowClothing();clxnWardrobe.Visible=true;clxnWardrobe.BringToFront();}
  Ped ClxnWardrobePed(){lock(RenderSyncRoot){var pin=ClxnProject.Pins.Find(p=>p.Id==clxnWardrobeActor);if(pin==null)return null;System.Threading.Tasks.Task<Ped> task;if(clxnActorLoads.TryGetValue(pin.Id+"|"+pin.AppearanceKey,out task)&&task.Status==System.Threading.Tasks.TaskStatus.RanToCompletion)return task.Result;return clxnActorLoads.Where(k=>k.Key.StartsWith(pin.Id+"|",StringComparison.Ordinal)&&k.Value.Status==System.Threading.Tasks.TaskStatus.RanToCompletion).Select(k=>k.Value.Result).FirstOrDefault();}}
  void ClxnShowClothing(){if(clxnClothingDrawable==null)return;ClxnClothingPart part;lock(ClxnProject.Sync)part=ClxnProject.Pins.Find(p=>p.Id==clxnWardrobeActor)?.Outfit.Find(p=>p.Component==clxnClothingComponent.SelectedIndex);clxnClothingUpdating=true;foreach(var n in new[]{clxnClothingDrawable,clxnClothingTexture,clxnClothingAlt})n.Maximum=10000;clxnClothingDrawable.Value=part?.Drawable??0;clxnClothingTexture.Value=part?.Texture??0;clxnClothingAlt.Value=part?.Alternative??0;clxnClothingYdd=part?.DrawablePath??"";clxnClothingYtd=part?.TexturePath??"";clxnWardrobeYdd=null;clxnWardrobeYtd=null;clxnClothingStatusKey=null;clxnClothingUpdating=false;ClxnUpdateClothingLimits();}
  void ClxnClothingFileLabel(){ClxnUpdateClothingLimits();}
  void ClxnUpdateClothingLimits(){if(clxnClothingUpdating)return;clxnClothingUpdating=true;try{
   int drawCount=0,textureCount=0,altCount=0;string source;
   if(!string.IsNullOrEmpty(clxnClothingYdd)){if(clxnWardrobeYdd==null){clxnWardrobeYdd=new YddFile();clxnWardrobeYdd.Load(ClxnReadResource(clxnClothingYdd));}drawCount=clxnWardrobeYdd.Drawables?.Length??0;source="YDD: "+Path.GetFileName(clxnClothingYdd);if(!string.IsNullOrEmpty(clxnClothingYtd)){if(clxnWardrobeYtd==null){clxnWardrobeYtd=new YtdFile();clxnWardrobeYtd.Load(ClxnReadResource(clxnClothingYtd));}textureCount=clxnWardrobeYtd.TextureDict?.Textures?.data_items?.Length??0;}}
   else{source="Источник: установленная GTA V";var ped=ClxnWardrobePed();if(ped==null){clxnClothingApply.Enabled=false;clxnClothingFiles.Text="Загрузка персонажа… Доступные варианты появятся автоматически.";return;}var variants=ped.Ymt?.VariationInfo?.GetComponentData(clxnClothingComponent.SelectedIndex)?.DrawblData3;drawCount=variants?.Length??0;if(drawCount>0){var item=variants[Math.Min((int)clxnClothingDrawable.Value,drawCount-1)];textureCount=item.TexData?.Length??0;altCount=item.NumAlternatives;}}
   if(!string.IsNullOrEmpty(clxnClothingYtd)){if(clxnWardrobeYtd==null){clxnWardrobeYtd=new YtdFile();clxnWardrobeYtd.Load(ClxnReadResource(clxnClothingYtd));}textureCount=clxnWardrobeYtd.TextureDict?.Textures?.data_items?.Length??0;source+=" / YTD: "+Path.GetFileName(clxnClothingYtd);}
   ClxnClothingLimit(clxnClothingDrawable,drawCount-1);ClxnClothingLimit(clxnClothingTexture,textureCount-1);ClxnClothingLimit(clxnClothingAlt,altCount);clxnClothingApply.Enabled=drawCount>0;clxnClothingFiles.Text=source+"\n"+(drawCount>0?"Вариантов: "+drawCount+" · текстур: "+textureCount+"\nИзмените номер и нажмите «Применить одежду».":"У этой модели нет одежды для выбранной детали.");
  }catch(Exception ex){clxnClothingApply.Enabled=false;clxnClothingFiles.Text="Ошибка ресурса: "+ex.Message;}finally{clxnClothingUpdating=false;}}
  static void ClxnClothingLimit(NumericUpDown n,int maximum){decimal max=Math.Max(0,maximum);if(n.Value>max)n.Value=max;n.Maximum=max;n.Enabled=maximum>0;}
  void ClxnWardrobeTick(){if(!clxnWardrobe.Visible)return;ClxnPin pin;lock(ClxnProject.Sync)pin=ClxnProject.Pins.Find(p=>p.Id==clxnWardrobeActor);if(pin==null){clxnWardrobe.Visible=false;return;}var key=pin.Id+"|"+pin.AppearanceKey;string error;if(clxnOutfitErrors.TryGetValue(key,out error)){clxnClothingFiles.Text="Не удалось применить: "+error;return;}if(clxnClothingStatusKey!=key&&ClxnWardrobePed()!=null){clxnClothingStatusKey=key;ClxnUpdateClothingLimits();}}
  static byte[] ClxnReadResource(string path){var f=new FileInfo(path);if(!f.Exists||f.Length>64*1024*1024)throw new IOException("Ресурс отсутствует или превышает 64 МБ: "+f.Name);return File.ReadAllBytes(path);}
  void ClxnChooseClothing(bool texture){using(var d=new OpenFileDialog{Title="Подключить совместимую одежду для модели персонажа",Filter=texture?"Словарь текстур|*.ytd":"Модель одежды|*.ydd"})if(d.ShowDialog(this)==DialogResult.OK)try{var bytes=ClxnReadResource(d.FileName);if(texture){var y=new YtdFile();y.Load(bytes);if(y.TextureDict?.Textures?.data_items?.Length>0){clxnClothingYtd=d.FileName;clxnWardrobeYtd=y;}else throw new FormatException("В YTD нет текстур.");}else{var y=new YddFile();y.Load(bytes);if(y.Drawables?.Length>0){clxnClothingYdd=d.FileName;clxnWardrobeYdd=y;}else throw new FormatException("В YDD нет моделей.");}ClxnClothingFileLabel();}catch(Exception ex){clxnMessage="Одежда не подключена: "+ex.Message;}}
  void ClxnSaveClothing(bool reset){if(!reset){ClxnUpdateClothingLimits();if(!clxnClothingApply.Enabled){clxnMessage=clxnClothingFiles.Text;return;}}lock(ClxnProject.Sync){var p=ClxnProject.Pins.Find(a=>a.Id==clxnWardrobeActor&&a.IsPed);if(p==null){clxnMessage="Этот персонаж уже удалён.";clxnWardrobe.Visible=false;if(clxnEnvironment!=null)clxnEnvironment.Visible=false;return;}ClxnProject.Checkpoint();p.Outfit.RemoveAll(o=>o.Component==clxnClothingComponent.SelectedIndex);if(!reset)p.Outfit.Add(new ClxnClothingPart{Component=clxnClothingComponent.SelectedIndex,Drawable=(int)clxnClothingDrawable.Value,Texture=(int)clxnClothingTexture.Value,Alternative=(int)clxnClothingAlt.Value,DrawablePath=clxnClothingYdd,TexturePath=clxnClothingYtd});}ClxnProject.Commit();clxnMessage="Одежда сохранена. Образ обновляется…";ClxnShowClothing();}
  string ClxnApplyOutfit(Ped ped,List<ClxnClothingPart> parts){var errors=new List<string>();foreach(var p in parts){var oldDrawable=ped.Drawables[p.Component];var oldTexture=ped.Textures[p.Component];try{
   if(string.IsNullOrEmpty(p.DrawablePath)){var variants=ped.Ymt?.VariationInfo?.GetComponentData(p.Component)?.DrawblData3;if(variants==null||p.Drawable>=variants.Length)throw new FormatException("Нет варианта "+p.Drawable+" для детали "+p.Component);var v=variants[p.Drawable];if((string.IsNullOrEmpty(p.TexturePath)&&v.TexData?.Length>0&&p.Texture>=v.TexData.Length)||p.Alternative>v.NumAlternatives)throw new FormatException("Нет выбранной текстуры или альтернативы.");ped.Textures[p.Component]=null;ped.Drawables[p.Component]=null;ped.SetComponentDrawable(p.Component,v.GetDrawableName(p.Alternative),(v.TexData?.Length??0)>0?v.GetTextureName(string.IsNullOrEmpty(p.TexturePath)?p.Texture:0):"",gameFileCache);if(ped.Drawables[p.Component]==null)throw new FormatException("Файл выбранной детали отсутствует в GTA V.");}
   else{var ydd=new YddFile();ydd.Load(ClxnReadResource(p.DrawablePath));if(ydd.Drawables==null||p.Drawable>=ydd.Drawables.Length)throw new FormatException("Индекс модели выходит за пределы YDD.");var drawable=(Drawable)ydd.Drawables[p.Drawable].ShallowCopy();if(!string.IsNullOrEmpty(p.TexturePath)){var ytd=new YtdFile();ytd.Load(ClxnReadResource(p.TexturePath));var textures=ytd.TextureDict?.Textures?.data_items;if(textures==null||p.Texture>=textures.Length)throw new FormatException("Индекс текстуры выходит за пределы YTD.");ped.Textures[p.Component]=textures[p.Texture];}else ped.Textures[p.Component]=null;ped.Drawables[p.Component]=drawable;}
   if(string.IsNullOrEmpty(p.DrawablePath)&&!string.IsNullOrEmpty(p.TexturePath)){var ytd=new YtdFile();ytd.Load(ClxnReadResource(p.TexturePath));var textures=ytd.TextureDict?.Textures?.data_items;if(textures==null||p.Texture>=textures.Length)throw new FormatException("Нет выбранной текстуры в YTD.");ped.Textures[p.Component]=textures[p.Texture];}
  }catch(Exception ex){ped.Drawables[p.Component]=oldDrawable;ped.Textures[p.Component]=oldTexture;errors.Add(ex.Message);clxnJournal.Add("Одежда: "+ex.Message+" Оставлена базовая деталь.");}}return errors.Count>0?string.Join("; ",errors):null;}
 }
